def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Diagonally aligned 1s define line segments.
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                cells = []
                r, c = r1, c1
                while True:
                    cells.append((r, c))
                    out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc
                segments.append((cells, dr, dc))

    # A 6 on a 1-segment extends along the opposite diagonal.
    for cells, dr, dc in segments:
        cellset = set(cells)
        for r, c in sixes:
            if (r, c) in cellset:
                # Rotate the segment direction by 90 degrees.
                ar, ac = dr, -dc
                for sign in (-1, 1):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != 1:
                            out[rr][cc] = 6
                        rr += sign * ar
                        cc += sign * ac

    # Preserve all input markers.
    for r, c in ones:
        out[r][c] = 1
    for r, c in sixes:
        out[r][c] = 6
    return out
